const baseRender=render,baseStart=startCareer,baseNext=nextSeason,baseFinish=finishSeason,baseFootball=football,baseOverview=overview,baseAbout=about,baseValidate=validateSave,baseMsg=msg;
let rollingOver=false;let worldLoaded=false;let clockTimer=null,matchTimer=null,marketFilter={search:'',position:'all',interest:false},marketTab='scouted';
const MS_DAY=86400000;
function dayAdd(s,n){return new Date(Date.parse(s+'T12:00:00Z')+n*MS_DAY).toISOString().slice(0,10)}
function daysBetween(a,b){return Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/MS_DAY)}
function iso(y,m,d){return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function dateText(s,long=true){return new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:long?'long':'short',day:'numeric',month:long?'long':'short',year:'numeric',timeZone:'UTC'})}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(rnd()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function seasonYear(){return 2025+g.season}
function windowState(date=g.world.date){let y=Number(date.slice(0,4)),md=date.slice(5);return md>='06-15'&&md<='09-01'?'Summer window open':md>='01-01'&&md<='02-01'?'Winter window open':'Transfer window closed'}
function windowOpen(){return windowState().includes('open')}
function addNews(title,body,kind='league'){g.world.news.unshift({title,body,date:g.world.date,kind});g.world.news=g.world.news.slice(0,100)}
msg=function(title,body,type='inbox'){baseMsg(title,body,type);if(g.world)g.inbox[0].date=g.world.date};
function calendarDates(y,count){let start=iso(y,8,tier()===0?22:15),end=iso(y+1,5,tier()===0?23:tier()===1?1:8),reserved=new Set([iso(y,11,7),iso(y,12,5),iso(y+1,1,9),iso(y+1,2,13),iso(y+1,3,6),iso(y+1,4,3),iso(y+1,4,24),iso(y+1,5,22)]),sats=[],mid=[];for(let d=start;d<=end;d=dayAdd(d,1)){let wd=new Date(d+'T12:00:00Z').getUTCDay();if(wd===6&&!reserved.has(d))sats.push(d);if(wd===2)mid.push(d)}if(sats.length>count)sats=sats.filter((d,i)=>i< count-1||i===sats.length-1);let need=count-sats.length;for(let i=0;i<need;i++)sats.push(mid[Math.floor((i+.5)*mid.length/need)]);return sats.sort()}
function setupWorld(qualification=null,preservedMarket=null){let y=seasonYear(),dates=calendarDates(y,rounds());g.world={schema:1,date:g.week===1?iso(y,7,1):dayAdd(dates[Math.min(g.week-2,dates.length-1)],1),days:0,news:[],scouted:[],shortlist:[],deals:{},transferred:[],sold:[],managerTrust:70,mentality:'balanced',tempo:'normal',boardTarget:tier()===0?'Finish in the top half':tier()===3?'Challenge for promotion':'Finish in the top half',fixtures:[],cups:{},live:null,ready:null,seasonComplete:false,leagueDone:g.week>rounds(),priorReview:g.history[0]?.season===g.season,qualification:qualification||null,foreign:[],marketOwners:preservedMarket||{}};
for(let i=g.week-1;i<rounds();i++){let p=g.schedules[tier()][i].find(p=>p.includes(g.clubId));g.world.fixtures.push({id:'L'+i,date:dates[i],comp:'League',round:'Matchweek '+(i+1),home:p[0],away:p[1],leagueRound:i+1,played:false})}
setupCups();scoutPlayers(true);addNews('A new season, a new story',`${club().name} begin preparations for ${DB[tier()].name}. Clubs are negotiating summer signings and supporters are looking ahead.`);save()}
function ensureWorld(){if(g&&!g.world)setupWorld();}
startCareer=function(id){stopClock();stopMatch();baseStart(id);if(!g.world)setupWorld();render();};
function externalClubs(){return [{id:'eu-real',name:'Real Madrid',short:'Real Madrid',strength:91},{id:'eu-barca',name:'FC Barcelona',short:'Barcelona',strength:88},{id:'eu-bayern',name:'Bayern Munich',short:'Bayern',strength:90},{id:'eu-psg',name:'Paris Saint-Germain',short:'PSG',strength:90},{id:'eu-inter',name:'Inter Milan',short:'Inter',strength:86},{id:'eu-juve',name:'Juventus',short:'Juventus',strength:84},{id:'eu-atleti',name:'Atlético Madrid',short:'Atlético',strength:85},{id:'eu-dortmund',name:'Borussia Dortmund',short:'Dortmund',strength:84},{id:'eu-benfica',name:'Benfica',short:'Benfica',strength:82},{id:'eu-porto',name:'FC Porto',short:'Porto',strength:81},{id:'eu-ajax',name:'Ajax',short:'Ajax',strength:80},{id:'eu-celtic',name:'Celtic',short:'Celtic',strength:76},{id:'eu-roma',name:'AS Roma',short:'Roma',strength:82},{id:'eu-lille',name:'Lille',short:'Lille',strength:79},{id:'eu-psv',name:'PSV Eindhoven',short:'PSV',strength:81},{id:'eu-sporting',name:'Sporting CP',short:'Sporting',strength:82},{id:'eu-fiorentina',name:'Fiorentina',short:'Fiorentina',strength:79},{id:'eu-betis',name:'Real Betis',short:'Real Betis',strength:79},{id:'eu-braga',name:'SC Braga',short:'Braga',strength:77},{id:'eu-basel',name:'FC Basel',short:'Basel',strength:73},{id:'eu-fener',name:'Fenerbahçe',short:'Fenerbahçe',strength:79},{id:'eu-ander',name:'Anderlecht',short:'Anderlecht',strength:73},{id:'eu-salzburg',name:'RB Salzburg',short:'Salzburg',strength:76},{id:'eu-athens',name:'AEK Athens',short:'AEK',strength:73}]}
function team(id){return club(id)||g.world.foreign.find(c=>c.id===id)||{id,name:'Cup opponent',short:'Opponent',strength:40}}
function teamBadge(id){let c=team(id);return c.badge?badge(c):`<span class="eurocrest">${esc(c.short.slice(0,3).toUpperCase())}</span>`}
function setupCups(){let w=g.world,y=seasonYear();w.foreign=externalClubs();let nonleague=Array.from({length:32},(_,i)=>({id:'nl-'+i,name:['Yorkshire','Northfield','Southport','Borough','County','Riverside','Eastbourne','Woking'][i%8]+' '+['Town','United','Athletic','Rovers'][Math.floor(i/8)],short:'Non-league club',strength:30+i%12}));w.foreign.push(...nonleague);
w.cups.FA={name:'FA Cup',key:'FA',round:-1,pool:shuffle([...g.divisions[2],...g.divisions[3],...nonleague.map(c=>c.id)]),results:[],draw:[],winners:[],dates:[iso(y,11,7),iso(y,12,5),iso(y+1,1,9),iso(y+1,2,13),iso(y+1,3,6),iso(y+1,4,3),iso(y+1,4,24),iso(y+1,5,22)],rounds:['First round','Second round','Third round','Fourth round','Fifth round','Quarter-final','Semi-final','Final'],winner:null};
w.cups.LC={name:'Carabao Cup',key:'LC',round:-1,pool:shuffle([...g.divisions[1],...g.divisions[2],...g.divisions[3]]),results:[],draw:[],winners:[],dates:[iso(y,8,4),iso(y,8,8),iso(y,8,26),iso(y,9,16),iso(y,10,28),iso(y,12,16),iso(y+1,1,13),iso(y+1,2,3),iso(y+1,3,21)],rounds:['Preliminary round','First round','Second round','Third round','Fourth round','Quarter-final','Semi-final · first leg','Semi-final · second leg','Final'],winner:null};w.cups.LC.europeSeeded=['359','382','360','362','364','349','366','384','331'].filter(id=>g.divisions[0].includes(id));for(let id of g.divisions[0])if(w.cups.LC.europeSeeded.length<9&&!w.cups.LC.europeSeeded.includes(id))w.cups.LC.europeSeeded.push(id);w.cups.LC.preliminary=g.divisions[3].filter(id=>['Rochdale','York City','Tranmere Rovers','Crawley Town'].includes(club(id).name));for(let id of [...g.divisions[3]].reverse())if(w.cups.LC.preliminary.length<4&&!w.cups.LC.preliminary.includes(id))w.cups.LC.preliminary.push(id);
let initial=tier()===0&&['359','382','360','362','364'].includes(g.clubId)?'Champions League':tier()===0&&['349','366','384'].includes(g.clubId)?'Europa League':tier()===0&&g.clubId==='331'?'Conference League':null;w.qualification=w.qualification||initial;
if(w.qualification&&w.qualification!=='none'){let key='EU',name=w.qualification;w.cups.EU={name,key,round:-1,pool:[g.clubId,...shuffle(externalClubs().map(c=>c.id)).slice(0,15)],results:[],draw:[],winners:[],dates:[iso(y,9,10),iso(y,9,24),iso(y,10,15),iso(y,11,5),iso(y,11,26),iso(y,12,10),iso(y+1,2,18),iso(y+1,3,18),iso(y+1,4,15),iso(y+1,5,29)],rounds:['League phase · 1','League phase · 2','League phase · 3','League phase · 4','League phase · 5','League phase · 6','Round of 16','Quarter-final','Semi-final','Final'],phaseTable:[],winner:null};for(let id of w.cups.EU.pool)w.cups.EU.phaseTable.push({id,p:0,pts:0,gf:0,ga:0})}
// Future real-world dates shift to the same weekday in subsequent simulated seasons.
if(g.season>1)for(let cup of Object.values(w.cups))cup.dates=cup.dates.map(d=>{let original=iso(2026+(Number(d.slice(0,4))>y?1:0),Number(d.slice(5,7)),Number(d.slice(8)));let wanted=new Date(original+'T12:00:00Z').getUTCDay(),actual=new Date(d+'T12:00:00Z').getUTCDay();return dayAdd(d,-((actual-wanted+7)%7))});
for(let cup of Object.values(w.cups))for(let i=0;i<cup.dates.length;i++)if(cup.dates[i]<w.date)cupRound(cup,i,true);
}
function allocateFixture(cup,pair,round,date){let f={id:cup.key+'-'+round+'-'+pair.join('-'),date,comp:cup.key,round:cup.rounds[round],home:pair[0],away:pair[1],played:false};if(pair.includes(g.clubId))g.world.fixtures.push(f);return f}
function cupRound(cup,r,catchup=false){if(cup.winner)return;if(cup.round>=r)return;cup.round=r;let pool=[];
if(cup.key==='FA'){pool=r===0?cup.pool:cup.winners;if(r===2)pool=[...pool,...g.divisions[0],...g.divisions[1]]}
if(cup.key==='LC'){if(r===0)pool=cup.preliminary;else if(r===1)pool=[...cup.pool.filter(id=>!cup.preliminary.includes(id)),...cup.winners];else if(r===2)pool=[...cup.winners,...g.divisions[0].filter(id=>!cup.europeSeeded.includes(id))];else if(r===3)pool=[...cup.winners,...cup.europeSeeded];else if(r===7)pool=cup.semiPairs.flat();else pool=cup.winners;}
if(cup.key==='EU'){if(r<6){let ids=[...cup.pool],pairs=[];for(let i=0;i<ids.length/2;i++){let a=ids[(i+r)%ids.length],b=ids[(ids.length-1-i+r)%ids.length];pairs.push(r%2?[b,a]:[a,b])}cup.draw=pairs;cup.winners=[];for(let pair of pairs){let f=allocateFixture(cup,pair,r,cup.dates[r]);if(!pair.includes(g.clubId)||catchup)resolveCupGame(cup,f,null,true)}return;}pool=r===6?[...cup.phaseTable].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)).map(t=>t.id):cup.winners;}
if(cup.key==='LC'&&r===7){cup.draw=cup.semiPairs.map(([a,b])=>[b,a]);}else{pool=shuffle(pool);cup.draw=[];for(let i=0;i<pool.length;i+=2)if(pool[i+1])cup.draw.push([pool[i],pool[i+1]]);}
if(cup.key==='LC'&&r===6){cup.semiPairs=cup.draw.map(p=>[...p]);cup.aggregates={};}
cup.winners=[];for(let pair of cup.draw){let f=allocateFixture(cup,pair,r,cup.dates[r]);if(!pair.includes(g.clubId)||catchup)resolveCupGame(cup,f,null,true)}if(!catchup&&cup.draw.some(p=>p.includes(g.clubId)))msg(cup.name+' draw',`You face ${team(cup.draw.find(p=>p.includes(g.clubId)).find(id=>id!==g.clubId)).name} in the ${cup.rounds[r]}.`,'football')}
function rawScore(a,b){let sa=a===g.clubId?squadRating():g.strengths[a]??team(a).strength,sb=b===g.clubId?squadRating():g.strengths[b]??team(b).strength;return [poisson(clamp(1.4+(sa-sb)*.035,.15,4)),poisson(clamp(1.1-(sa-sb)*.035,.15,4))]}
function resolveCupGame(cup,f,score=null,quiet=false){let [a,b]=score||rawScore(f.home,f.away),winner=null,penalties=false;if(cup.key==='EU'&&cup.round<6){for(let [id,x,y] of [[f.home,a,b],[f.away,b,a]]){let t=cup.phaseTable.find(t=>t.id===id);t.p++;t.gf+=x;t.ga+=y;t.pts+=x>y?3:x===y?1:0}}else if(cup.key==='LC'&&(cup.round===6||cup.round===7)){cup.aggregates[f.home]=(cup.aggregates[f.home]||0)+a;cup.aggregates[f.away]=(cup.aggregates[f.away]||0)+b;if(cup.round===7){let aa=cup.aggregates[f.home],bb=cup.aggregates[f.away];winner=aa>bb?f.home:aa<bb?f.away:(rnd()>.5?f.home:f.away);penalties=aa===bb;cup.winners.push(winner)}}else{winner=a>b?f.home:a<b?f.away:(rnd()>.5?f.home:f.away);penalties=a===b;cup.winners.push(winner)}f.played=true;f.score=[a,b];f.penalties=penalties;f.winner=winner;cup.results.push({...f});if(winner&&cup.draw.length===1&&cup.round===cup.rounds.length-1){cup.winner=winner;addNews(team(winner).name+' win the '+cup.name,'The final is decided. '+team(f.home).name+' '+a+'–'+b+' '+team(f.away).name+(penalties?' — settled on penalties.':'.'),'cup')}
if([f.home,f.away].includes(g.clubId)&&!quiet){let own=f.home===g.clubId?a:b,opp=f.home===g.clubId?b:a;let prize=typeof cupPrize==='function'?cupPrize(cup.key,cup.round):0,revenue=Math.round((f.home===g.clubId?g.capacity*.8*g.ticket*.6:0)+(winner===g.clubId?Math.max(prize,cfg[tier()].fee*.02):Math.round(prize*.35)));g.cash+=revenue;record(cup.name+' match receipts & prize money',revenue);g.morale=clamp(g.morale+(own>opp?3:own<opp?-3:0),10,100);msg(cup.name+' · '+f.round,`${team(f.home).name} ${a}–${b} ${team(f.away).name}.${penalties?' '+team(winner).name+' progress on penalties.':''} ${money(revenue)} in match income and prize money.`,'football');if(winner===g.clubId&&cup.winner)g.trust=clamp(g.trust+10,5,100)}return f}
function applyScore(table,a,b,score){for(let [id,f,c] of [[a,score[0],score[1]],[b,score[1],score[0]]]){let t=table.find(t=>t.id===id);t.p++;t.gf+=f;t.ga+=c;let s=f>c?'W':f===c?'D':'L';t.form.push(s);t.form=t.form.slice(-5);if(s==='W'){t.w++;t.pts+=3}else if(s==='D'){t.d++;t.pts++}else t.l++}}
function settleLeague(f,score){if(f.played)return;for(let d=0;d<4;d++){let round=g.schedules[d][g.week-1];if(!round)continue;for(let [a,b] of round){if(a===g.clubId||b===g.clubId)applyScore(g.tables[d],a,b,score);else simulate(a,b,g.tables[d])}}f.played=true;f.score=score;let own=f.home===g.clubId?score[0]:score[1],opp=f.home===g.clubId?score[1]:score[0],result=own>opp?'W':own===opp?'D':'L';let attendance=0;if(f.home===g.clubId){attendance=Math.round(clamp(g.fans*(.85+g.trust*.003)*Math.pow([38,27,22,18][tier()]/g.ticket,.9)*(.92+rnd()*.16),0,g.capacity-(g.upgrades.some(u=>u.id==='stand')?400:0)));let income=Math.round(attendance*(g.ticket+4+g.hospitality*[3,2.5,2,1.5][tier()]));g.cash+=income;record('League matchday receipts',income)}g.morale=clamp(g.morale+({W:3,D:0,L:-3}[result]),10,100);g.trust=clamp(g.trust+({W:1.5,D:0,L:-1.5}[result]),5,100);g.fans=Math.round(clamp(g.fans*({W:1.006,D:1,L:.996}[result]),500,g.capacity*1.5));g.last={home:f.home===g.clubId,for:own,against:opp,opponent:f.home===g.clubId?f.away:f.home,result,week:g.week};msg(result==='W'?'Three points secured':result==='D'?'A point on the board':'A difficult afternoon',`${team(f.home).name} ${score[0]}–${score[1]} ${team(f.away).name}.${attendance?' Attendance: '+attendance.toLocaleString():''}`,'football');g.week++;if(g.week>rounds())g.world.leagueDone=true;addNews('Around '+DB[tier()].name,`${standings()[0]?team(standings()[0].id).name:'The leaders'} lead the table. ${club().name} sit ${position()} with ${myrow().pts} points.`)}
function centralWeekly(){return cfg[tier()].income}
function centralForecast(t){return cfg[t].income}
function weeklyWorld(){let items=[],add=(n,v)=>{v=Math.round(v);g.cash+=v;items.push([n,v])};add('Broadcast & central distributions',centralWeekly());for(let d of g.sponsors){let remainWeeks=Math.max(1,Math.ceil(daysBetween(g.world.date,iso(seasonYear()+1,5,31))/7));let payment=Math.round(d.remaining/remainWeeks);d.remaining-=payment;add(d.name+' instalment',payment)}add('First-team wages',-squadWages());add('Manager & operating staff',-g.manager.wage-g.staff);add('Stadium & utilities',-g.capacity*1.1);add('Academy operations',-youthCost());if(g.debt)add('Loan interest',-g.debt*.0015);if(g.policy==='push')add('Performance preparation',-cfg[tier()].wage*.04);if(g.cash<0)add('Overdraft interest',g.cash*.003);g.ledger.unshift({season:g.season,week:g.week,date:g.world.date,items,net:items.reduce((s,x)=>s+x[1],0)});g.ledger=g.ledger.slice(0,60);development();for(let u of g.upgrades){u.left--;if(u.left===0){if(u.id==='stand')g.capacity+=1000;if(u.id==='hospitality')g.hospitality++;if(u.id==='academy')g.youth.facility++;msg('Project complete',u.name+' is operational.','stadium')}}g.upgrades=g.upgrades.filter(u=>u.left>0);if(g.cash < -cfg[tier()].cash*.5){g.ended=true;stopClock();msg('Administration','The club has exceeded its overdraft facility. This career has ended.')};scoutPlayers(false);worldNews();}
function worldNews(){let w=g.world,others=CLUBS.filter(c=>c.id!==g.clubId),a=others[Math.floor(rnd()*others.length)];if(windowOpen()&&rnd()>.35){let buyer=others.filter(c=>c.id!==a.id)[Math.floor(rnd()*(others.length-1))],players=a.players.filter(p=>!w.transferred.includes(p.id)&&!g.squad.some(x=>x.id===p.id)),p=players[Math.floor(rnd()*players.length)];if(p){let m=marketPlayer(p,a.id);w.marketOwners[p.id]=buyer.id;addNews(buyer.name+' complete '+p.name+' signing',`${p.name} joins from ${a.name} in a ${compact(m.ask)} deal. The move is reflected in the transfer market.`,'transfer')}}else{let row=g.tables.flat().find(t=>t.id===a.id),type=Math.floor(rnd()*3);if(type===0)addNews('Pressure building at '+a.name,`${row?.l>=row?.w?'Recent results have put the manager under scrutiny.':'The board have reiterated their ambitions for the season.'} Supporters are watching the next fixtures closely.`);else if(type===1)addNews(a.name+' invest in youth','The club have announced a renewed focus on their academy and scouting network.');else addNews(a.name+' commercial update','A new regional partnership has been announced as the club look to strengthen recurring income.')}}
function eventsToday(){let w=g.world;for(let cup of Object.values(w.cups)){let r=cup.dates.indexOf(w.date);if(r>=0)cupRound(cup,r)}let f=w.fixtures.find(f=>!f.played&&f.date<=w.date);if(f){w.ready=f.id;stopClock();save();render();matchDecision(f);return true}if(w.date>=iso(seasonYear()+1,5,31)&&w.leagueDone&&!w.seasonComplete){completeWorldSeason();stopClock();return true}return false}
function nextFixture(){return g.world.fixtures.filter(f=>!f.played&&f.date>=g.world.date).sort((a,b)=>a.date.localeCompare(b.date))[0]}
function stopClock(){if(clockTimer){clearInterval(clockTimer);clockTimer=null}if($('advance')&&g?.world)$('advance').innerHTML=g.world.seasonComplete?'Next season →':g.world.live?'Match in progress':g.world.ready?'Matchday →':'Continue ▷'}
function advanceDay(){if(g.ended||g.world.live)return stopClock();let w=g.world;if(eventsToday())return;let previous=windowState();w.date=dayAdd(w.date,1);w.days++;if(w.days%7===0)weeklyWorld();if(previous!==windowState()){msg(windowState(),windowOpen()?'Player registrations are now open. Visit recruitment to negotiate.':'The registration deadline has passed. Continue scouting for the next window.','football');addNews(windowState(),'Clubs across England turn their attention to the next phase of the season.','transfer')}processDeals();if(w.pauseReason)stopClock();if(w.days%7===0||w.date.slice(-2)==='01')save();render();eventsToday();}
advance=function(){ensureWorld();if(g.ended)return;if(g.world.live){page='Matchday';render();return}if(g.world.seasonComplete)return nextSeason();if(g.world.ready){let f=g.world.fixtures.find(f=>f.id===g.world.ready);if(f&&!f.played)return matchDecision(f);g.world.ready=null}if(clockTimer){stopClock();render();return}if(eventsToday())return;g.world.pauseReason=null;clockTimer=setInterval(advanceDay,Number($('calendarSpeed')?.value||350));render()};
function stepDay(){stopClock();advanceDay()}
function completeWorldSeason(){if(!g.world.priorReview)baseFinish();let p=position(),cups=g.world.cups,eu=p<=4&&tier()===0?'Champions League':p<=6&&tier()===0?'Europa League':p===7&&tier()===0?'Conference League':null;if(cups.FA.winner===g.clubId&&eu!=='Champions League')eu='Europa League';if(cups.LC.winner===g.clubId&&!eu)eu='Conference League';g.world.nextQualification=eu;g.world.seasonComplete=true;let target=position()<=(g.world.boardTarget.includes('promotion')?4:Math.ceil(g.tables[tier()].length/2));g.world.managerTrust=clamp(g.world.managerTrust+(target?8:-8),5,100);msg('Board season review',`${target?'The board are satisfied with the league finish.':'The league finish fell short of the board’s top-half expectation.'} ${eu?'You have qualified for the '+eu+'.':'No European qualification this season.'}`);save();render()}
nextSeason=function(){stopClock();if(rollingOver)return;if(!g.world?.seasonComplete){if(g.week>rounds()&&g.world.date>=iso(seasonYear()+1,5,31)){g.world.leagueDone=true;completeWorldSeason()}else return toast('The season continues until the remaining cup competitions are settled.')}let off=Math.round(weeklyCosts()*6),eu=g.world.nextQualification;$('modal').innerHTML=`<div class="overlay"><div class="modal"><div class="eyebrow">A NEW CHAPTER</div><h1>Ready for next season?</h1><p>Your completed season and club history will be kept. Promotions and relegations will be applied, contracts updated, and the new calendar will begin on 1 July.</p><div class="row"><span>Off-season operating costs</span><b>${money(off)}</b></div><div class="row"><span>Current cash</span><b>${money(g.cash)}</b></div><p>${eu?'European qualification: '+esc(eu)+'.':'No European qualification for the coming season.'}</p><div class="actions"><button class="primary" onclick="performSeasonRollover()">Start next season →</button><button onclick="closeModal()">Review club first</button></div></div></div>`};
function performSeasonRollover(){if(rollingOver||!g.world?.seasonComplete)return;let backup=JSON.stringify(g),oldSeason=g.season,eu=g.world.nextQualification,owners={...g.world.marketOwners};rollingOver=true;try{baseNext(true);if(g.season!==oldSeason+1)throw Error('Season did not advance');g.world=null;setupWorld(eu||'none',owners);closeModal();page='Overview';save();rollingOver=false;render();toast('Welcome to the new season. Your career has been saved.')}catch(error){g=JSON.parse(backup);rollingOver=false;save();closeModal();render();toast('The new season could not start. Your previous career has been restored. Export your save so the issue can be checked.');console.error('Season rollover failed',error)}}

function marketPlayer(p,owner){let ownerId=g.world.marketOwners[p.id]||owner,t=club(owner)?.league??2;let h=Math.abs(hash(p.id)),rating=clamp(cfg[t].quality-9+h%190/10,30,94),base=cfg[t].fee*(.5+(rating-cfg[t].quality+10)/12),age=p.age+g.season-1,ask=Math.round(Math.max(10000,base*(age<23?1.25:age>31?.65:1))/1000)*1000;return {...p,owner:ownerId,age,rating,potential:clamp(rating+(age<23?16:6),rating,98),ask,wage:Math.round(cfg[t].wage/23*(.8+(h%9)/10)),generated:false}}
function marketList(){let own=new Set(g.squad.map(p=>p.id)),seen=new Set();let result=[];for(let c of CLUBS)for(let p of c.players){let owner=g.world.marketOwners[p.id]||c.id;if(owner===g.clubId||own.has(p.id)||seen.has(p.id)||g.world.transferred.includes(p.id))continue;seen.add(p.id);result.push(marketPlayer(p,c.id))}for(let p of g.world.sold)if(!own.has(p.id)&&!seen.has(p.id))result.push(p);return result}
function willingness(p){let sourceTier=g.divisions.findIndex(d=>d.includes(p.owner)),gap=tier()-sourceTier,qualityGap=p.rating-squadRating();if(gap>=2||qualityGap>16)return {label:'Not interested',code:'no',reason:'The player considers this a step too far down in sporting level.'};if(gap===1||qualityGap>7)return {label:'Needs convincing',code:'maybe',reason:'They would need an important squad role and a stronger wage offer.'};return {label:'Open to talks',code:'yes',reason:'The club’s level and project suit this player.'}}
function scoutPlayers(initial=false){if(!g.world)return;let list=marketList().filter(p=>willingness(p).code!=='no'&&p.ask<g.cash*.8&&p.rating>squadRating()-8);if(!list.length)list=marketList().filter(p=>willingness(p).code!=='no');let picked=shuffle(list).slice(0,4);g.world.scouted=[...new Set([...picked.map(p=>p.id),...g.world.scouted])].slice(0,20);if(!initial&&picked.length)msg('Scout report: '+picked[0].name,`${team(picked[0].owner).name}'s ${picked[0].position} is worth a closer look. Estimated fee ${money(picked[0].ask)}. ${willingness(picked[0]).label}.`,'football')}
function shortPlayer(id){let a=g.world.shortlist,i=a.indexOf(id);if(i>=0)a.splice(i,1);else a.push(id);save();render()}
function negotiatePlayer(id){stopClock();let p=marketList().find(p=>p.id===id);if(!p)return toast('The player is no longer on the market.');let interest=willingness(p),d=g.world.deals[id];if(d?.status==='signed')return;if(!windowOpen())return toast('The transfer window is closed. Add the player to your shortlist for the next window.');if(d?.closed)return toast('These talks have broken down. Revisit the player next season.');g.world.deals[id]=d||{player:p,status:'club',tries:0,stage:'club'};showTransfer(id)}
function showTransfer(id){stopClock();let d=g.world.deals[id],p=d.player,interest=willingness(p),stage=d.stage;let awaiting=d.status==='awaiting';$('modal').innerHTML=`<div class="overlay"><div class="modal"><div class="topline"><span class="eyebrow">${stage==='club'?'CLUB NEGOTIATION':'PLAYER CONTRACT'}</span><button class="textbutton" onclick="closeModal()">Close ×</button></div><h1>${esc(p.name)}</h1><p>${esc(team(p.owner).name)} · ${p.position} · ${p.age} years · ${Math.round(p.rating)} rating</p><span class="pill ${interest.code==='no'?'negative':''}">${interest.label}</span><p>${interest.reason}</p>${stage==='club'?`<label>Offer transfer fee (£)</label><input id="transferFee" type="number" min="0" value="${d.fee||p.ask}"><p>Selling club asking price: ${money(p.ask)}. The club can reject or counter your offer.</p>`:`<div class="notice">Club fee agreed: ${money(d.fee)}. Now agree terms with the player.</div><label>Weekly wage (£)</label><input id="transferWage" type="number" min="1" value="${d.wage||p.wage}"><label>Contract length</label><select id="transferYears"><option value="2">2 years</option><option value="3" selected>3 years</option><option value="4">4 years</option></select><label>Promised squad role</label><select id="transferRole"><option value="rotation">Rotation player</option><option value="first">First-team regular</option><option value="key">Key player</option></select>`}<div id="transferReply" class="notice">${esc(d.reply||'Submit your proposal. The response will arrive after one or two game days.')}</div><button class="primary" ${awaiting?'disabled':''} onclick="submitTransfer('${id}')">${awaiting?'Awaiting response…':'Send offer →'}</button></div></div>`}
function submitTransfer(id){let d=g.world.deals[id];if(!d||d.closed||d.status==='awaiting'||!windowOpen())return;let p=d.player;if(d.stage==='club'){let v=Math.round(Number($('transferFee').value));if(!Number.isFinite(v)||v<1||v>g.cash)return toast('Enter an affordable positive transfer fee.');d.fee=v}else{let wage=Math.round(Number($('transferWage').value)),years=Number($('transferYears').value),role=$('transferRole').value;if(!Number.isFinite(wage)||wage<1||wage>cfg[tier()].cash*.05||![2,3,4].includes(years)||!['rotation','first','key'].includes(role))return toast('Choose valid contract terms.');d.wage=wage;d.years=years;d.role=role}d.status='awaiting';d.respondOn=dayAdd(g.world.date,1+Math.floor(rnd()*2));d.reply='Your proposal has been sent. Continue time to receive a response.';save();showTransfer(id)}
function processDeals(){for(let [id,d] of Object.entries(g.world.deals)){if(d.status!=='awaiting'||d.respondOn>g.world.date)continue;let p=marketList().find(p=>p.id===id);if(!p||p.owner!==d.player.owner){d.status='rejected';d.closed=true;d.reply='The player has moved or is no longer available.';msg('Transfer talks ended',d.player.name+': '+d.reply,'football');continue}if(!windowOpen()){d.status='rejected';d.reply='The registration deadline has passed. No money was spent.';msg('Transfer window closed',d.player.name+': '+d.reply,'football');continue}d.tries++;if(d.stage==='club'){let floor=p.ask*(.9+(Math.abs(hash(p.id))%10)/100);if(d.fee<floor){d.status='counter';d.reply=`The club want ${money(Math.round(floor/1000)*1000)}. Your fee was rejected.`;if(d.tries>=3)d.closed=true}else{d.stage='player';d.status='club-agreed';d.reply='The selling club have accepted. Negotiate a contract with the player.';d.tries=0}}else{let interest=willingness(p),need=Math.round(p.wage*(interest.code==='maybe'?1.35:1)*(d.role==='rotation'?1.15:d.role==='key'?.95:1));if(interest.code==='no'){d.status='rejected';d.closed=true;d.reply='The player has declined the move on sporting grounds.'}else if(d.wage<need){d.status='counter';d.reply=`The agent asks for at least ${money(need)} per week for this role.`;if(d.tries>=3)d.closed=true}else if(g.cash<d.fee){d.status='rejected';d.reply='The club can no longer afford the agreed fee.'}else if(g.squad.length>=35){d.status='rejected';d.reply='The first-team squad is full. Make space before completing the deal.'}else{g.cash-=d.fee;record('Transfer fee: '+p.name,-d.fee);g.squad.push({...p,wage:d.wage,contract:d.years,promisedRole:d.role,rating:p.rating,potential:p.potential});g.world.transferred.push(p.id);g.world.marketOwners[p.id]=g.clubId;d.status='signed';d.reply=`Transfer completed for ${money(d.fee)} on ${money(d.wage)} a week.`;addNews(club().name+' sign '+p.name,d.reply,'transfer')}}msg('Transfer update: '+d.player.name,d.reply,'football');g.world.pauseReason='A transfer response needs your attention.';save()}}
sellPlayer=function(id){if(g.ended||g.world.live)return toast('Player sales are unavailable right now.');if(!windowOpen())return toast('Player sales can complete during an open transfer window.');if(g.squad.length<=16)return toast('Keep at least 16 first-team players.');let p=g.squad.find(p=>p.id===id);if(!p)return;let fee=playerValue(p);if(!confirm(`Accept an offer of ${money(fee)} for ${p.name}?`))return;let buyers=CLUBS.filter(c=>c.id!==g.clubId&&Math.abs(c.league-tier())<=1),buyer=buyers[Math.floor(rnd()*buyers.length)];g.cash+=fee;record('Player sale: '+p.name,fee);g.squad=g.squad.filter(x=>x.id!==id);g.world.marketOwners[id]=buyer.id;g.world.sold.push({...p,owner:buyer.id,ask:Math.round(fee*1.15)});g.world.transferred=g.world.transferred.filter(x=>x!==id);addNews(buyer.name+' sign '+p.name,`${club().name} receive ${money(fee)} for the transfer.`,'transfer');save();render()};
buyPlayer=function(){go('Recruitment')};
function matchDecision(f){if(f.played)return;stopClock();let c=f.comp==='League'?DB[tier()].name:g.world.cups[f.comp].name;$('modal').innerHTML=`<div class="overlay"><div class="modal"><div class="eyebrow">MATCHDAY · ${dateText(f.date)}</div><h1>${esc(c)}</h1><p>${esc(f.round)}</p><div class="teams"><div class="team">${teamBadge(f.home)}<p>${esc(team(f.home).name)}</p></div><div class="vs">VS</div><div class="team">${teamBadge(f.away)}<p>${esc(team(f.away).name)}</p></div></div><p>Attend to watch the match unfold and send requests to your manager. Delegate to let the manager handle the afternoon.</p><div class="actions"><button class="primary" onclick="beginMatch('${f.id}',true)">Attend match →</button><button onclick="beginMatch('${f.id}',false)">Delegate to manager</button><button onclick="closeModal()">Back to club</button></div></div></div>`}
function beginMatch(id,attend=true){let f=g.world.fixtures.find(f=>f.id===id);if(!f||f.played||g.world.live)return;closeModal();g.world.ready=null;g.world.live={fixture:id,minute:0,home:0,away:0,homeXg:0,awayXg:0,stamina:100,paused:attend,speed:2,halftime:false,mentality:g.world.mentality,tempo:g.world.tempo,commands:0,lastCommand:-10,commentary:[{minute:0,text:'The teams emerge. Your manager is preparing for kick-off.'}]};if(!attend){while(g.world.live&&g.world.live.minute<90)tickMatch(true);finishMatch();}else{page='Matchday';save();render()}}
function stopMatch(){if(matchTimer){clearInterval(matchTimer);matchTimer=null}}
function playMatch(){let l=g.world.live;if(!l)return;stopMatch();l.paused=!l.paused;if(!l.paused)matchTimer=setInterval(()=>tickMatch(false),Math.max(70,900/l.speed));save();render()}
function matchSpeed(v){let l=g.world.live;if(!l)return;l.speed=Number(v);stopMatch();if(!l.paused)matchTimer=setInterval(()=>tickMatch(false),Math.max(70,900/l.speed));save()}
function tickMatch(delegate=false){let l=g.world.live;if(!l)return stopMatch();let f=g.world.fixtures.find(f=>f.id===l.fixture),home=f.home===g.clubId,ownStrength=squadRating()+(g.manager.skill-60)*.12+(g.morale-65)*.06,oppId=home?f.away:f.home,oppStrength=g.strengths[oppId]??team(oppId).strength,adv=home?1.18:1;let ownRate=clamp(1.3+(ownStrength-oppStrength)*.04,.25,3.5)*adv,oppRate=clamp(1.15-(ownStrength-oppStrength)*.035,.2,3.4);if(l.mentality==='attacking'){ownRate*=1.3;oppRate*=1.22}if(l.mentality==='defensive'){ownRate*=.7;oppRate*=.72}if(l.tempo==='high'){ownRate*=1.12;oppRate*=1.08;l.stamina-=.7}else l.stamina-=.3;if(l.minute>65&&l.stamina<65)oppRate*=1.2;l.minute++;let homeRate=home?ownRate:oppRate,awayRate=home?oppRate:ownRate;l.homeXg+=homeRate/90;l.awayXg+=awayRate/90;for(let [key,rate] of [['home',homeRate],['away',awayRate]]){if(rnd()<rate/90){l[key]++;let isOwn=key==='home'?home:!home,scorer=isOwn?g.squad.filter(p=>!['GK','G'].includes(p.position))[Math.floor(rnd()*Math.max(1,g.squad.filter(p=>!['GK','G'].includes(p.position)).length))]?.name:null;l.commentary.unshift({minute:l.minute,text:`GOAL! ${team(key==='home'?f.home:f.away).name}${scorer?' — '+scorer:''}. ${l.home}–${l.away}.`})}}if(l.minute%9===0)l.commentary.unshift({minute:l.minute,text:[`${team(home?g.clubId:oppId).short} look to build through midfield.`,`The manager gestures for ${l.mentality==='attacking'?'more bodies forward':l.mentality==='defensive'?'a compact defensive shape':'composure on the ball'}.`,'A chance from the edge of the area, but the goalkeeper deals with it.','The crowd respond as the tempo lifts.'][Math.floor(rnd()*4)]});l.commentary=l.commentary.slice(0,35);if(l.minute===45&&!delegate&&!l.halftime){l.halftime=true;l.paused=true;stopMatch();l.commentary.unshift({minute:45,text:'Half-time. Speak to your manager and review the approach.'});save();render();return}if(l.minute>=90){if(!delegate)finishMatch();return}if(!delegate){if(l.minute%5===0)save();render()}}
function managerRequest(kind){let l=g.world.live;if(!l)return;let f=g.world.fixtures.find(f=>f.id===l.fixture);if(l.minute-l.lastCommand<5&&l.minute!==45)return toast('Give the manager a few minutes to respond to your last request.');let accepted=rnd()<clamp(.45+g.world.managerTrust*.005-l.commands*.035,.2,.95);l.commands++;l.lastCommand=l.minute;g.world.managerTrust=clamp(g.world.managerTrust-(l.commands>3?3:1),5,100);if(accepted){if(['attacking','balanced','defensive'].includes(kind))l.mentality=kind;if(['high','normal'].includes(kind))l.tempo=kind;if(kind==='encourage')g.morale=clamp(g.morale+2,10,100);l.commentary.unshift({minute:l.minute,text:`Manager: “Understood. ${kind==='encourage'?'I’ll encourage the players.':kind==='high'?'We’ll raise the tempo.':kind==='normal'?'We’ll manage the tempo.':'We’ll use a '+kind+' approach.'}”`})}else l.commentary.unshift({minute:l.minute,text:'Manager: “I understand, but I’m sticking with my judgement for now.”'});save();render()}
function finishMatch(){stopMatch();let l=g.world.live;if(!l)return;let f=g.world.fixtures.find(f=>f.id===l.fixture);if(!f||f.played){g.world.live=null;return}let score=[l.home,l.away];if(f.comp==='League')settleLeague(f,score);else resolveCupGame(g.world.cups[f.comp],f,score);g.world.lastMatch={...l,date:f.date,comp:f.comp,homeId:f.home,awayId:f.away,round:f.round,penalties:f.penalties,winner:f.winner};g.world.live=null;g.world.ready=null;save();page='Matchday';render()}
function matchPage(){let l=g.world.live,last=g.world.lastMatch;if(!l&&!last){let f=nextFixture();return card('Matchday',`<div class="pad"><h2>Your seat is waiting.</h2><p>${f?`Next fixture: ${dateText(f.date)} · ${team(f.home).name} v ${team(f.away).name}`:'Your next fixture will appear here after the cup draw or new season.'}</p><button class="primary" onclick="advance()">Continue towards matchday →</button></div>`)}let f=l?g.world.fixtures.find(f=>f.id===l.fixture):{home:last.homeId,away:last.awayId,date:last.date,comp:last.comp,round:last.round},state=l||last;return `<div class="matchscore"><div class="eyebrow">${f.comp==='League'?DB[tier()].name:g.world.cups[f.comp]?.name||f.comp} · ${esc(f.round)}</div><div class="scoreteams"><div>${teamBadge(f.home)}<h2>${esc(team(f.home).name)}</h2></div><div class="scorecentral"><strong>${state.home} <span>–</span> ${state.away}</strong><small>${l?(l.minute===45&&l.paused?'HALF-TIME':l.minute+'′'+(l.paused?' · PAUSED':'')):'FULL-TIME'}${last?.penalties&&!l?' · '+team(last.winner).short+' win on penalties':''}</small></div><div>${teamBadge(f.away)}<h2>${esc(team(f.away).name)}</h2></div></div><p>${dateText(f.date)} · ${f.comp==='FA'&&f.round==='Final'||f.comp==='LC'&&f.round==='Final'?'Wembley Stadium':esc(team(f.home).stadium||'European away ground')}</p>${l?`<div class="matchcontrols"><button class="primary" onclick="playMatch()">${l.paused?(l.minute===0?'Kick off ▷':'Resume ▷'):'Pause Ⅱ'}</button><label>Match speed <select onchange="matchSpeed(this.value)">${[1,2,4,8].map(n=>`<option value="${n}" ${l.speed===n?'selected':''}>${n}×</option>`).join('')}</select></label></div>`:'<button class="primary" onclick="go(\'Overview\')">Return to the boardroom →</button>'}</div><div class="columns" style="margin-top:22px">${card('Live commentary',`<div class="matchfeed">${state.commentary.map(e=>`<div class="row"><b>${e.minute}′</b><p>${esc(e.text)}</p></div>`).join('')}</div>`)}<div class="stack">${card('Manager communication',`<div class="pad"><h2>${esc(g.manager.name)}</h2><p>Relationship: ${Math.round(g.world.managerTrust)}/100. Requests can influence the match, but your manager can disagree. Repeated interference damages trust.</p>${l?`<span class="pill">${l.mentality.toUpperCase()} · ${l.tempo.toUpperCase()} TEMPO</span><div class="actions"><button onclick="managerRequest('attacking')">Push forward</button><button onclick="managerRequest('balanced')">Stay balanced</button><button onclick="managerRequest('defensive')">Protect the lead</button><button onclick="managerRequest('high')">Raise tempo</button><button onclick="managerRequest('normal')">Manage tempo</button><button onclick="managerRequest('encourage')">Encourage players</button></div>`:'<p>The final whistle has gone. Review the result and plan your next move.</p>'}</div>`)}${card('Match statistics',`<div class="pad"><div class="row"><b>${state.homeXg.toFixed(2)}</b><span>Expected goals</span><b>${state.awayXg.toFixed(2)}</b></div><div class="row"><span>Approach</span><b>${esc(state.mentality)}</b></div><div class="row"><span>Energy remaining</span><b>${Math.round(state.stamina)}%</b></div></div>`)}</div></div>`}
function recruitment(){let list=marketList(),scouted=new Set(g.world.scouted),short=new Set(g.world.shortlist);if(marketTab==='scouted')list=list.filter(p=>scouted.has(p.id));if(marketTab==='shortlist')list=list.filter(p=>short.has(p.id));if(marketFilter.search)list=list.filter(p=>(p.name+' '+team(p.owner).name).toLowerCase().includes(marketFilter.search.toLowerCase()));if(marketFilter.position!=='all')list=list.filter(p=>p.position===marketFilter.position);if(marketFilter.interest)list=list.filter(p=>willingness(p).code!=='no');list.sort((a,b)=>b.rating-a.rating);let deals=Object.entries(g.world.deals).filter(([id,d])=>d.status!=='signed');return `<div class="notice ${windowOpen()?'':'warning'}"><b>${windowState()}</b> · ${dateText(g.world.date)}<br>Summer: 15 June–1 September. Winter: 1 January–1 February. Scout at any time; transfers must complete before the registration deadline.</div><div class="twocol">${card('Your recruitment team',`<div class="pad"><p>Scouts recommend affordable players who could suit your level. Search the full database or build a shortlist. Club fees and player contracts are negotiated separately, with replies arriving after 1–2 game days.</p><button onclick="scoutPlayers(false);save();render()">Request fresh scout reports</button></div>`)}${card('Active negotiations',`<div class="pad">${deals.length?deals.slice(0,5).map(([id,d])=>`<div class="row"><div><h3>${esc(d.player.name)}</h3><small>${esc(d.reply||'Talks started')} ${d.respondOn&&d.status==='awaiting'?'Reply due '+dateText(d.respondOn,false):''}</small></div><button onclick="showTransfer('${id}')" ${d.closed?'disabled':''}>${d.status==='awaiting'?'View':'Respond'}</button></div>`).join(''):'<p>No talks underway. Start with your scout recommendations.</p>'}</div>`)}</div><div class="tabs">${[['scouted','Scout recommendations'],['all','Player search'],['shortlist','Shortlist']].map(([k,n])=>`<button class="${marketTab===k?'active':''}" onclick="marketTab='${k}';render()">${n}</button>`).join('')}</div><div class="marketfilters"><input aria-label="Search players or clubs" placeholder="Search player or club…" value="${esc(marketFilter.search)}" onchange="marketFilter.search=this.value;render()"><select aria-label="Position" onchange="marketFilter.position=this.value;render()">${['all','GK','DEF','MID','FWD','CB','CM','ST'].map(p=>`<option value="${p}" ${marketFilter.position===p?'selected':''}>${p==='all'?'All positions':p}</option>`).join('')}</select><label><input type="checkbox" ${marketFilter.interest?'checked':''} onchange="marketFilter.interest=this.checked;render()"> Interested players only</label></div>${card(list.length+' players found',`<div class="tablewrap"><table class="markettable"><thead><tr><th>PLAYER</th><th>CLUB</th><th>AGE</th><th>RATING</th><th>ASKING FEE</th><th>INTEREST</th><th></th></tr></thead><tbody>${list.slice(0,80).map(p=>{let i=willingness(p);return `<tr><td><b>${esc(p.name)}</b><small>${p.position}</small></td><td><div class="clubcell">${teamBadge(p.owner)}${esc(team(p.owner).short)}</div></td><td>${p.age}</td><td>${Math.round(p.rating)}</td><td>${compact(p.ask)}</td><td class="${i.code==='no'?'negative':i.code==='yes'?'positive':''}">${i.label}</td><td><button class="iconbutton" onclick="shortPlayer('${p.id}')">${short.has(p.id)?'★':'☆'}</button> <button class="iconbutton" onclick="negotiatePlayer('${p.id}')" ${!windowOpen()?'disabled':''}>Approach</button></td></tr>`}).join('')}</tbody></table></div>${list.length>80?'<p style="padding:0 20px">Showing the first 80 results. Refine your search to find a particular player.</p>':''}`)}`}
function competitionPage(){let cups=Object.values(g.world.cups);return `<div class="cards">${cups.map(c=>{let mine=c.results.filter(f=>f.home===g.clubId||f.away===g.clubId),last=mine.at(-1),active=!last?.winner||last.winner===g.clubId||c.key==='EU'&&c.round<6||c.key==='LC'&&c.round===6,entered=c.pool.includes(g.clubId)||c.key==='FA'||c.key==='LC';return `<div class="card pad"><div class="eyebrow">${c.key==='EU'?'EUROPEAN FOOTBALL':'DOMESTIC CUP'}</div><h2 style="font-size:30px;margin:14px 0">${c.name}</h2><span class="pill">${c.winner?'WINNER: '+team(c.winner).name:c.round<0?'DRAW AWAITED':c.rounds[c.round]}</span><p>${c.key==='FA'?'League One and Two enter in November. Premier League and Championship enter in January.':c.key==='LC'?'All 92 professional clubs. Two-legged semi-finals and a Wembley final.':'A condensed European campaign: six league-phase matches, then a 16-team knockout. All league-phase entrants advance in this edition.'}</p>${last?`<p>Your last tie: ${team(last.home).short} ${last.score[0]}–${last.score[1]} ${team(last.away).short}${last.penalties?' (penalties)':''}</p>`:'<p>Your cup story is waiting to be written.</p>'}<h3>Next round date</h3><p>${c.dates[c.round+1]?dateText(c.dates[c.round+1]):'Competition complete'}</p></div>`}).join('')}${!g.world.cups.EU?`<div class="card pad"><div class="eyebrow">EUROPEAN AMBITION</div><h2 style="font-size:30px;margin-top:14px">Earn your place.</h2><p>Premier League top four qualify for the Champions League, fifth and sixth for the Europa League, seventh for the Conference League. FA Cup and Carabao Cup wins also offer routes into Europe.</p><span class="pill">NOT QUALIFIED THIS SEASON</span></div>`:''}</div><div class="sectiontitle"><h2>Cup results & draws</h2></div>${cups.map(c=>card(c.name,`<div class="pad">${c.draw.length?c.draw.map(pair=>{let result=[...c.results].reverse().find(f=>f.home===pair[0]&&f.away===pair[1]&&f.round===c.rounds[c.round]);return `<div class="row ${pair.includes(g.clubId)?'positive':''}"><span>${esc(team(pair[0]).name)}</span><b>${result?result.score.join(' – ')+(result.penalties?' pens':''):'v'}</b><span>${esc(team(pair[1]).name)}</span></div>`}).join(''):'<p>Draw not yet made.</p>'}</div>`)).join('<div style="height:20px"></div>')}<div class="notice">Domestic round dates and entry stages are based on the 2026/27 calendar. Non-league FA Cup opponents and future results are simulated. European competitions use a condensed 16-team format, not the full UEFA 36-team format.</div>`}
function calendarPage(){let events=[...g.world.fixtures].sort((a,b)=>a.date.localeCompare(b.date));return `<div class="calendarhero"><div><div class="eyebrow">THE FOOTBALL CALENDAR</div><h2>${dateText(g.world.date)}</h2><p>${windowState()} · ${clockTimer?'Time is advancing':'Time paused'}</p></div><div class="actions"><button class="primary" onclick="advance()">${clockTimer?'Pause time Ⅱ':'Continue time ▷'}</button><button onclick="stepDay()">Advance one day</button><label>Calendar pace <select id="calendarSpeed" onchange="if(clockTimer){stopClock();advance()}"><option value="700">Relaxed</option><option value="350" selected>Normal</option><option value="100">Fast</option></select></label></div></div>${card('Your fixtures',`<div class="tablewrap"><table><thead><tr><th>DATE</th><th>COMPETITION</th><th>HOME</th><th>AWAY</th><th>RESULT</th></tr></thead><tbody>${events.map(f=>`<tr class="${f.date===g.world.date?'us':''}"><td>${dateText(f.date,false)}</td><td>${f.comp==='League'?DB[tier()].name:g.world.cups[f.comp]?.name}</td><td>${esc(team(f.home).name)}</td><td>${esc(team(f.away).name)}</td><td>${f.played?f.score.join('–')+(f.penalties?' pens':''):'15:00'}</td></tr>`).join('')}</tbody></table></div>`)}<p>Future cup ties appear when each draw is made. League fixture dates are generated for this career, rather than copied from the live fixture list.</p>`}
function newsPage(){return card('The football world',`<div class="pad"><p>News reflects your simulated career: transfers, cup results, league races and club announcements. These are game stories, not live real-world reports.</p></div>${g.world.news.map(n=>`<div class="inboxitem"><span class="itemicon">${icon(n.kind==='transfer'?'Football':n.kind==='cup'?'League':'Inbox')}</span><div><span class="eyebrow">${dateText(n.date,false)}</span><h3 style="margin-top:8px">${esc(n.title)}</h3><p>${esc(n.body)}</p></div></div>`).join('')}`)}
football=function(){let full=baseFootball(),split=full.indexOf('<div class="sectiontitle">');return `<div class="twocol">${card('Your manager',`<div class="pad"><h2>${esc(g.manager.name)}</h2><p>Ability ${g.manager.skill}/100 · ${money(g.manager.wage)}/week<br>Relationship ${g.world.managerTrust}/100</p><label>Default match approach</label><select onchange="g.world.mentality=this.value;save()">${['balanced','attacking','defensive'].map(v=>`<option ${g.world.mentality===v?'selected':''} value="${v}">${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select><p>Attend matches to request tactical changes. The manager balances your requests against their own judgement.</p><button onclick="hireManager()">Recruit a stronger manager · ${compact(cfg[tier()].fee*.35)}</button></div>`)}${card('Recruitment & expectations',`<div class="pad"><h2>${g.squad.length} first-team players</h2><p>${money(squadWages())} weekly payroll.<br>Board ambition: ${esc(g.world.boardTarget)}.</p><p>Your scouts bring suggestions. Search the market, negotiate fees and convince players to join your project.</p><button class="primary" onclick="go('Recruitment')">Open recruitment centre →</button><button onclick="go('Matchday')" style="margin-top:10px">Enter match centre</button></div>`)}</div>`+(split>=0?full.slice(split):'')};
nextMatch=function(){let f=nextFixture();if(!f)return `<div class="matchbox"><h2>${g.world.seasonComplete?'Season complete':'Waiting for the draw'}</h2><p>${g.world.seasonComplete?'Your next chapter awaits.':'Continue time for the next cup draw or season review.'}</p><button class="primary" onclick="advance()">Continue →</button></div>`;return `<div class="matchbox"><div class="eyebrow">${f.comp==='League'?DB[tier()].name:g.world.cups[f.comp]?.name} · ${esc(f.round)}</div><div class="teams"><div class="team">${teamBadge(f.home)}<div>${esc(team(f.home).short)}</div></div><div class="vs">VS</div><div class="team">${teamBadge(f.away)}<div>${esc(team(f.away).short)}</div></div></div><p>${dateText(f.date)}<br>${esc(team(f.home).stadium||'European venue')}</p><span class="pill">${f.home===g.clubId?'HOME':'AWAY'} FIXTURE</span><button onclick="${g.world.ready?`matchDecision(g.world.fixtures.find(f=>f.id==='${f.id}'))`:'go(\'Calendar\')'}">${g.world.ready?'Attend or delegate →':'View calendar ↗'}</button></div>`};
overview=function(){return `<div class="worldstrip"><span><b>${dateText(g.world.date)}</b> · ${windowState()}</span><span>${clockTimer?'◉ Time advancing':'Ⅱ Time paused'} <button class="textbutton" onclick="go('Calendar')">Calendar ↗</button></span></div>`+baseOverview()+`<div class="sectiontitle"><h2>Around the football world</h2><button class="textbutton" onclick="go('News')">All news ↗</button></div>${newsPage().replace('The football world','World news')}`};
forecast=function(){let end=dayAdd(g.world.date,91),home=g.world.fixtures.filter(f=>!f.played&&f.home===g.clubId&&f.date<=end).length,matchincome=home*Math.min(g.capacity,g.fans)*(g.ticket+4+g.hospitality*[3,2.5,2,1.5][tier()]),weeksleft=Math.max(1,Math.ceil(daysBetween(g.world.date,iso(seasonYear()+1,5,31))/7)),sponsor=g.sponsors.reduce((s,d)=>s+d.remaining*Math.min(13/weeksleft,1),0);return Math.round(g.cash+matchincome+sponsor+13*(centralForecast(tier())-weeklyCosts()))};
render=function(){if(!g||rollingOver)return;ensureWorld();if(!worldLoaded){worldLoaded=true;if(g.world.live)g.world.live.paused=true;}let custom=['Recruitment','Competitions','Calendar','News','Matchday'].includes(page),wanted=page;if(custom)page='Overview';baseRender();page=wanted;let additions=['Recruitment','Competitions','Calendar','News','Matchday'];let nav=$('nav');nav.innerHTML=['Overview','Finances','Sponsorship','Football','Recruitment','Academy','Stadium','League','Competitions','Calendar','News','Inbox','Matchday'].map(p=>`<button class="${p===page?'active':''}" onclick="go('${p}')">${icon(({Recruitment:'Football',Competitions:'League',Calendar:'Overview',News:'Inbox',Matchday:'Football'})[p]||p)}<span>${p==='Football'?'First team':p}</span>${p==='Academy'?`<span class="count">${g.prospects.length}</span>`:''}</button>`).join('');if(custom){let labels={Recruitment:['BUILD YOUR SQUAD','Recruitment centre','Discover talent. Agree the deal. Sell the project.'],Competitions:['CHASE THE SILVERWARE','Cup & European competitions','A cup run can change everything.'],Calendar:['ONE DAY AT A TIME','Season calendar','Let the football world unfold around you.'],News:['THE WIDER GAME','World news','The stories shaping your simulated football world.'],Matchday:['FROM THE DIRECTORS’ BOX','Match centre','Watch the match and speak to your manager.']};[$('subtitle').textContent,$('title').textContent,$('intro').textContent]=labels[page];$('content').innerHTML=({Recruitment:recruitment,Competitions:competitionPage,Calendar:calendarPage,News:newsPage,Matchday:matchPage}[page]());$('breadcrumb').textContent=page}$('date').textContent=dateText(g.world.date,false);$('advance').innerHTML=g.world.live?'Match in progress':g.world.seasonComplete?'Next season →':g.world.ready?'Matchday →':clockTimer?'Pause Ⅱ':'Continue ▷';$('advance').disabled=g.ended;if(g.world.pauseReason)$('content').insertAdjacentHTML('afterbegin',`<div class="notice">${esc(g.world.pauseReason)} <button class="textbutton" onclick="go('Recruitment')">Open recruitment →</button></div>`);};
about=function(){$('modal').innerHTML=`<div class="overlay"><div class="modal"><div class="topline"><span class="eyebrow">THE BOARDROOM · LIVING WORLD EDITION</span><button class="textbutton" onclick="closeModal()">Close ×</button></div><h1>A football world<br>on your terms.</h1><p>Manage ownership, commercial deals, finances, recruitment, facilities and academy development. Continue time through the calendar; it stops at fixtures and transfer responses. Attend matches to watch timed commentary and communicate with your manager, or delegate.</p><p>Real clubs and player names use a 2026/27 reference snapshot. All ratings, values, salaries, contracts, results, future transfers and news are simulated. There is no live sports feed.</p><p>Summer registrations: 15 June–1 September. Winter: 1 January–1 February. Dates follow the published 2026/27 English windows; later seasons repeat those month/day boundaries. League schedules are generated. Domestic cup dates and entry stages follow the reference season. Non-league opponents are fictional.</p><p>Promotions and relegations preserve 20/24/24/24 clubs. Direct promotion replaces play-offs in this edition; there is no relegation below League Two. European qualification: Premier League top four to Champions League, fifth/sixth to Europa League, seventh to Conference League; FA Cup and Carabao Cup winners gain routes to Europe. European campaigns use six league-phase matches with all 16 entrants advancing to a knockout tournament, rather than the full UEFA format.</p><p>Finances, academy development and construction progress every seven calendar days. Match receipts and transfer fees are separate transactions. First-team contracts renew automatically at expiry with an 8% wage increase. Six weeks of off-season costs are charged when starting the next campaign.</p><p>Careers autosave in this browser. Export to back up or move between devices. Existing v2 careers upgrade automatically; original v1 saves remain stored separately. Time runs only while this page is open, and attended matches resume paused after reloading.</p><div class="source">Reference sources: <a href="https://www.espn.com/soccer/" target="_blank" rel="noopener">ESPN</a>, <a href="https://www.premierleague.com/en/clubs" target="_blank" rel="noopener">Premier League</a>, <a href="https://www.efl.com/" target="_blank" rel="noopener">EFL</a> and <a href="https://www.thefa.com/competitions/thefacup/round-dates" target="_blank" rel="noopener">The FA</a>. Stadium/player images: TheSportsDB, Wikipedia/Wikimedia Commons and credited image sources. <a href="asset-credits.json" target="_blank">Asset credits</a>. Unavailable images use illustrations. Marks belong to their respective owners. Independent prototype; not an officially licensed football product.</div></div></div>`};
const originalImport=importSave;importSave=function(e){stopClock();stopMatch();worldLoaded=false;originalImport(e)};
validateSave=function(x){baseValidate(x);if(x.world){let w=x.world;if(w.schema!==1||!/^\d{4}-\d{2}-\d{2}$/.test(w.date)||!Number.isFinite(Date.parse(w.date+'T12:00:00Z'))||!Array.isArray(w.fixtures)||!Array.isArray(w.news)||!Array.isArray(w.scouted)||!Array.isArray(w.shortlist)||!Array.isArray(w.sold)||!w.cups||!w.deals||!w.marketOwners||!Array.isArray(w.foreign)||!Number.isFinite(w.managerTrust))throw Error('Invalid world');for(let f of w.fixtures)if(typeof f.id!=='string'||! /^[a-zA-Z0-9-]+$/.test(f.id)||typeof f.home!=='string'||typeof f.away!=='string')throw Error('Invalid fixture')}return true};

const originalNewGame=newGame;newGame=function(){stopClock();stopMatch();if(g?.world?.live)g.world.live.paused=true;originalNewGame()};
